import test from 'node:test';
import assert from 'node:assert/strict';
import { createMissionEngine } from '../src/lib/foundation/mission.js';
import { createDialogueQueue } from '../src/lib/foundation/dialogue.js';
const memory=()=>{const data=new Map();return {getItem:k=>data.get(k)??null,setItem:(k,v)=>data.set(k,v)};};
const offer={id:'medical-1',title:'Medical supplies',destination:'Morna Station',reward:80};
const advance=e=>{e.dispatch({type:'offer',mission:offer});for(const type of ['accept','depart','arrive'])e.dispatch({type});};
test('completion survives reload and pays only once',()=>{const storage=memory(),e=createMissionEngine({storage});advance(e);e.dispatch({type:'complete'});const resumed=createMissionEngine({storage});resumed.dispatch({type:'complete'});assert.equal(resumed.snapshot().credits,80);assert.equal(resumed.snapshot().ledger.length,1);});
test('completion before arrival is rejected',()=>{const e=createMissionEngine({storage:memory()});e.dispatch({type:'offer',mission:offer});assert.throws(()=>e.dispatch({type:'complete'}),/transition/i);assert.equal(e.snapshot().credits,0);});
test('save failure leaves rewards and mission untouched',()=>{const storage=memory(),e=createMissionEngine({storage});advance(e);storage.setItem=()=>{throw Error('Storage full');};assert.throws(()=>e.dispatch({type:'complete'}),/Storage full/);assert.equal(e.snapshot().credits,0);assert.equal(e.snapshot().mission.status,'arrived');});
test('corrupt saves are reported without being overwritten',()=>{const storage=memory();storage.setItem('mole-beyond:foundation:v1','broken');assert.throws(()=>createMissionEngine({storage}),/save/i);assert.equal(storage.getItem('mole-beyond:foundation:v1'),'broken');});
test('invalid reward and replay payout are rejected',()=>{const e=createMissionEngine({storage:memory()});assert.throws(()=>e.dispatch({type:'offer',mission:{...offer,reward:-1}}),/reward/i);advance(e);e.dispatch({type:'complete'});assert.throws(()=>e.dispatch({type:'offer',mission:offer}),/already/i);});
test('choices persist and cannot change during travel',()=>{const storage=memory(),e=createMissionEngine({storage});e.dispatch({type:'offer',mission:offer});e.dispatch({type:'choose',choice:'humanitarian'});const r=createMissionEngine({storage});assert.equal(r.snapshot().story.path,'humanitarian');r.dispatch({type:'accept'});r.dispatch({type:'depart'});assert.throws(()=>r.dispatch({type:'choose',choice:'discreet'}),/transition/i);});
test('snapshots cannot change internal state',()=>{const e=createMissionEngine({storage:memory()});e.snapshot().credits=999;assert.equal(e.snapshot().credits,0);});
const tick=()=>new Promise(r=>setTimeout(r,0));
test('dialogue waits until each line finishes',async()=>{const calls=[];let release;const q=createDialogueQueue({play:item=>{calls.push(item.text);return new Promise(r=>{release=r;});}});const a=q.enqueue({text:'First'}),b=q.enqueue({text:'Second'});await tick();assert.deepEqual(calls,['First']);release();await a;await tick();assert.deepEqual(calls,['First','Second']);release();assert.equal(await b,'played');});
test('safety preempts story and clears queued chatter',async()=>{const calls=[];const q=createDialogueQueue({play:(item,signal)=>{calls.push(item.text);return new Promise(r=>signal.addEventListener('abort',r,{once:true}));}});const a=q.enqueue({text:'Story'}),b=q.enqueue({text:'More story'});await tick();const c=q.enqueue({text:'Safety',priority:'safety'});await tick();assert.deepEqual(calls,['Story','Safety']);assert.equal(await a,'cancelled');assert.equal(await b,'cancelled');q.clear();assert.equal(await c,'cancelled');});
test('audio failure does not block later lines',async()=>{const q=createDialogueQueue({play:async item=>{if(item.text==='Bad')throw Error('Audio unavailable');}});const a=q.enqueue({text:'Bad'}),b=q.enqueue({text:'Good'});assert.equal(await a,'failed');assert.equal(await b,'played');});
test('a stale second session cannot overwrite new rewards',()=>{const storage=memory();const first=createMissionEngine({storage}),second=createMissionEngine({storage});advance(first);first.dispatch({type:'complete'});assert.throws(()=>second.dispatch({type:'offer',mission:{...offer,id:'other'}}),/another session/i);assert.equal(createMissionEngine({storage}).snapshot().credits,80);});
test('unsafe save balances are rejected',()=>{const storage=memory();storage.setItem('mole-beyond:foundation:v1',JSON.stringify({version:1,revision:1,credits:999,ledger:[],mission:null,story:{path:'standard'}}));assert.throws(()=>createMissionEngine({storage}),/save/i);});
test('simulated travel progress is saved and arrival requires completing the route',()=>{const storage=memory();const e=createMissionEngine({storage});e.dispatch({type:'offer',mission:{...offer,distanceKm:2}});e.dispatch({type:'accept'});e.dispatch({type:'depart'});assert.throws(()=>e.dispatch({type:'arrive'}),/route/i);e.dispatch({type:'travel',distanceKm:1});const r=createMissionEngine({storage});assert.equal(r.snapshot().mission.travelledKm,1);r.dispatch({type:'travel',distanceKm:5});assert.equal(r.snapshot().mission.travelledKm,2);r.dispatch({type:'arrive'});r.dispatch({type:'complete'});assert.equal(r.snapshot().credits,80);});
test('travel rejects negative, non-finite and parked movement',()=>{const e=createMissionEngine({storage:memory()});e.dispatch({type:'offer',mission:{...offer,distanceKm:2}});assert.throws(()=>e.dispatch({type:'travel',distanceKm:1}),/transition/i);e.dispatch({type:'accept'});e.dispatch({type:'depart'});for(const n of [-1,NaN,Infinity])assert.throws(()=>e.dispatch({type:'travel',distanceKm:n}),/distance/i);});

